// Generated by Tessa from plans/create-ticket/tests.json (run 20261016T080102Z).
// Story: Editors can create tickets; viewers cannot
// Sessions come from stored storage state files; see README.md. No credentials are in this file.
import { expect, test } from '@playwright/test';

test.describe('Editors can create tickets; viewers cannot', () => {
  test.describe('as editor', () => {
    // Signed-in session for editor; see README.md.
    test.use({ storageState: process.env.TESSA_AUTH_EDITOR ?? '.auth/editor.json' });

    test(
      'Editor creates a high-priority ticket',
      {
        tag: ['@create-ticket', '@editor', '@happy-path'],
        annotation: [
          {
            type: 'intent',
            description: 'Proves an editor can create a ticket and lands on its detail page.',
          },
          { type: 'seed-profile', description: 'default' },
          { type: 'criterion', description: 'ac-1' },
        ],
      },
      async ({ page }) => {
        await page.goto('/tickets');
        await test.step('Click New ticket', async () => {
          await page.getByTestId('create-ticket').click();
        });
        await test.step('Enter a title', async () => {
          await page.getByLabel('Title').fill('Export button is misaligned');
        });
        await test.step('Choose high priority', async () => {
          await page.getByTestId('ticket-priority').selectOption('high');
        });
        await test.step('Submit the form', async () => {
          await page.getByRole('button', { name: 'Create ticket' }).click();
        });
        await test.step('The ticket detail page opens', async () => {
          await expect(page).toHaveURL(new RegExp('^[a-z][a-z0-9+.-]*://[^/]+/tickets/[0-9]+$'));
        });
        await test.step('Priority shows high', async () => {
          await expect(page.getByTestId('ticket-priority-value')).toHaveText('high');
        });
      },
    );
  });

  test.describe('as viewer', () => {
    // Signed-in session for viewer; see README.md.
    test.use({ storageState: process.env.TESSA_AUTH_VIEWER ?? '.auth/viewer.json' });

    test(
      'Viewer cannot open the new ticket form',
      {
        tag: ['@create-ticket', '@viewer'],
        annotation: [
          {
            type: 'intent',
            description:
              'Proves the create permission is enforced in navigation and on the server.',
          },
          { type: 'seed-profile', description: 'default' },
          { type: 'criterion', description: 'ac-3' },
        ],
      },
      async ({ page }) => {
        await page.goto('/tickets');
        await test.step('No New ticket link in the navigation', async () => {
          await expect(page.getByTestId('nav-new-ticket')).toHaveCount(0);
        });
        await test.step('Go to the form directly', async () => {
          await page.goto('/tickets/new');
        });
        await test.step('A permission error is shown', async () => {
          await expect(page.getByRole('alert')).toContainText('permission');
        });
      },
    );
  });
});
